import json

ALLOWED = {"title", "priority", "estimate_hours"}

def validate_ticket(raw):
    try:
        data = json.loads(raw)
    except (ValueError, TypeError):
        return None, ["invalid json"]
    if not isinstance(data, dict):
        return None, ["invalid json"]
    errors = []
    title = data.get("title")
    if not isinstance(title, str) or not title.strip():
        errors.append("title required")
    if data.get("priority") not in ("low", "medium", "high"):
        errors.append("bad priority")
    est = data.get("estimate_hours")
    if isinstance(est, bool) or not isinstance(est, (int, float)) or est < 0:
        errors.append("bad estimate")
    for key in sorted(set(data) - ALLOWED):
        errors.append("unexpected key: " + key)
    if errors:
        return None, errors
    return data, []
